#include "hal/registers.h"
#include "hal/constants.h"

// Forward declaration of your actual OS main function
void kernel_main(void);

// External symbols generated by your custom common.ld script
extern unsigned int __stack_top;
extern unsigned int _data_lma;
extern unsigned int _data_start;
extern unsigned int _data_end;
extern unsigned int __bss_start;
extern unsigned int __BSS_END__;


// The absolute first C function executed by the hardware
__attribute__((section(".text.entry"), naked)) void _start(void) {
    // 1. Setup the Stack Pointer immediately using inline assembly.
    // The "naked" attribute prevents the compiler from generating its own 
    // stack entry code before this instruction runs.
    asm volatile (
        "la sp, __stack_top \n"
        "la gp, __global_pointer$ \n"
    );

    // 2. Clear BSS (Zero-initialize uninitialized global variables)
    unsigned int *bss = &__bss_start;
    while (bss < &__BSS_END__) {
        *bss++ = 0;
    }

    // 3. Copy Initialized Global Data from Flash (LMA) to RAM (VMA)
    unsigned int *src = &_data_lma;
    unsigned int *dst = &_data_start;
    while (dst < &_data_end) {
        *dst++ = *src++;
    }

    // 4. Safely jump to your high-level C code now that hardware is ready
    kernel_main();

    // Fallback trap loop if kernel_main ever returns
    while(1) {
        asm volatile("nop");
    }
}

// Simple delay function loop
__attribute__((noinline)) void delay_cycles(volatile unsigned int count) {
    while(count--) {
        asm volatile("nop");
    }
}

// Longer delay for visible blinking (~1 second per half-cycle at 80MHz)
void delay_ms(unsigned int ms) {
    // At 80 MHz, roughly 80 cycles per loop iteration with the inner loop
    // ~1250 iterations per ms, so multiply by 1250
    for (unsigned int i = 0; i < ms; i++) {
        delay_cycles(1250);
    }
}

void disable_watchdogs(void) {
    const unsigned int rwdt_disable_mask = (1U << 31) | (0xFFFU << 19) | (1U << 12);
    const unsigned int mwdt_disable_mask = (1U << 31) | (0xFFFU << 23) | (1U << 14);
    // 1. Disable RTC Watchdog (RWDT)
    *RTC_CNTL_WDTWPROTECT_REG = 0x50D83AA1;  // Unlock RTC write protection
    *RTC_CNTL_WDTCONFIG0_REG &= ~rwdt_disable_mask;    // Clear WDT_ENABLE bit
    *RTC_CNTL_WDTWPROTECT_REG = 0;             // Re-lock

    // 2. Disable Timer Group 0 Watchdog (MWDT)
    *TIMG_WDTWPROTECT_REG = 0x50D83AA1;       // Unlock TIMG0 write protection
    *TIMG_WDTFEED_REG = 1;
    *TIMG_INT_CLR_TIMERS_REG = (1U << 1);
    *TIMG_WDTCONFIG0_REG &= ~mwdt_disable_mask;       // Clear WDT_ENABLE bit
    *TIMG_WDTCONFIG0_REG |= (1U << 22);
    *TIMG_WDTWPROTECT_REG = 0;                // Re-lock

    // 3. Disable Super WDT (SWD) — ESP32-C3 has its own separate WPROTECT register
    // The Super WDT timeout is configured by SWD_CONF (bits 0-10).
    // Setting it to 0 disables the timeout entirely.
    *RTC_CNTL_SWD_WPROTECT_REG = RTC_CNTL_SWD_WPROTECT_KEY;  // Unlock SWD
    *RTC_CNTL_SWD_CONF_REG |= (1U << 30);                               // Disable SWD timeout
    *RTC_CNTL_SWD_WPROTECT_REG = 0;                           // Re-lock
}

void putchar(char c){
    *USB_SERIAL_JTAG_EP1_REG = (unsigned int)c;
}

void print(const char* str){
    while(*str) putchar(*str++);
    *USB_SERIAL_JTAG_EP1_CONF_REG = (1U << 0);
}

void kernel_main(void) {
    disable_watchdogs();

    // ESP32-C3 Super Mini: built-in LED is on GPIO8 (PORT0, bit 8)
    const int led_gpio = 8;

    // 1. Enable output mode on GPIO3
    *GPIO_ENABLE_REG |= (1U << led_gpio);

    *GPIO_OUT_REG &= ~(1U << led_gpio);
    delay_ms(3000);
    print("LED ON\r\n");
    *GPIO_OUT_REG |= (1U << led_gpio);
    delay_ms(1000);
    print("LED OFF\r\n");

    // 2. Continuous blink loop
    while (1) {
        // Clear bit 8 -> Turns LED ON (Active Low)
        *GPIO_OUT_REG &= ~(1U << led_gpio);
        print("LED ON\r\n");
        delay_ms(500);

        // Set bit 8 -> Turns LED OFF
        *GPIO_OUT_REG |= (1U << led_gpio);
        print("LED OFF\r\n");
        delay_ms(500);
    }
}
